  "version": 1,
  "patientIdColumn": "patient_id",
  "populationQuery": {
    "extractFrom": "sqlTemplate"
  },
  "supportsRedisaggregation": true,
  "redisaggregationStrategy": "population-extraction",
  "themeIndependent": true,
  "dataSources": [
    "mamba_fact_encounter_hiv_art_summary"
  ],
  "sqlTemplate": "SELECT DISTINCT s.patient_id\nFROM mamba_fact_encounter_hiv_art_summary s\nWHERE s.baseline_regimen_start_date BETWEEN :startDate AND :endDate\n  AND s.baseline_cd4 IS NOT NULL\n  AND TRIM(s.baseline_cd4) &lt;&gt; '';",
  "sqlPreview": "SELECT DISTINCT s.patient_id AS patient_id FROM mamba_fact_encounter_hiv_art_summary s\nWHERE s.baseline_regimen_start_date BETWEEN :startDate AND :endDate\n  AND s.baseline_cd4 IS NOT NULL\n  AND TRIM(s.baseline_cd4) &lt;&gt; '';"
}
